From 4e42d2f2e47c8ffb588a41f2429ab08cc7860993 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 18:44:48 +0100
Subject: [PATCH] applets/notifications: add a global shortcut to hide
 notification popups

Popups that never time out could only be removed by closing each one. A
new "Hide Notification Popups" global shortcut hides them all as if they
had timed out, so they stay in the history and running jobs go on.

BUG: 500308
---
 applets/notifications/global/Globals.qml  | 15 +++++++++++++++
 applets/notifications/globalshortcuts.cpp | 10 ++++++++++
 applets/notifications/globalshortcuts.h   |  2 ++
 3 files changed, 27 insertions(+)

diff --git a/applets/notifications/global/Globals.qml b/applets/notifications/global/Globals.qml
index 8e8e56f88d..2f74559a75 100644
--- a/applets/notifications/global/Globals.qml
+++ b/applets/notifications/global/Globals.qml
@@ -795,8 +795,23 @@ QtObject {
         }
     }

+    function hideAllPopups() {
+        let popups = [];
+        for (let i = 0; i < popupInstantiator.count; ++i) {
+            popups.push(popupInstantiator.objectAt(i));
+        }
+        popups.forEach(popup => {
+            if (popup.dismissable) {
+                popup.model.dismissed = true;
+            } else {
+                popup.expired();
+            }
+        });
+    }
+
     property Notifications.GlobalShortcuts shortcuts: Notifications.GlobalShortcuts {
         onToggleDoNotDisturbTriggered: globals.toggleDoNotDisturbMode()
         onClearHistoryTriggered: plasmoidItem.clearNotificationHistoryAndShowOsd()
+        onHidePopupsTriggered: globals.hideAllPopups()
     }
 }
diff --git a/applets/notifications/globalshortcuts.cpp b/applets/notifications/globalshortcuts.cpp
index c3613d49ad..e05b3f0df2 100644
--- a/applets/notifications/globalshortcuts.cpp
+++ b/applets/notifications/globalshortcuts.cpp
@@ -18,6 +18,7 @@ GlobalShortcuts::GlobalShortcuts(QObject *parent)
     : QObject(parent)
     , m_toggleDoNotDisturbAction(new QAction(this))
     , m_clearHistoryAction(new QAction(this))
+    , m_hidePopupsAction(new QAction(this))
 {
     m_toggleDoNotDisturbAction->setObjectName(QStringLiteral("toggle do not disturb"));
     m_toggleDoNotDisturbAction->setProperty("componentName", QStringLiteral("plasmashell"));
@@ -36,6 +37,15 @@ GlobalShortcuts::GlobalShortcuts(QObject *parent)
     connect(m_clearHistoryAction, &QAction::triggered, this, &GlobalShortcuts::clearHistoryTriggered);

     KGlobalAccel::self()->setGlobalShortcut(m_clearHistoryAction, QKeySequence());
+
+    m_hidePopupsAction->setObjectName(QStringLiteral("hide popups"));
+    m_hidePopupsAction->setProperty("componentName", QStringLiteral("plasmashell"));
+    m_hidePopupsAction->setText(i18nc("@action", "Hide Notification Popups"));
+    m_hidePopupsAction->setIcon(QIcon::fromTheme(QStringLiteral("notifications")));
+    m_hidePopupsAction->setShortcutContext(Qt::ApplicationShortcut);
+    connect(m_hidePopupsAction, &QAction::triggered, this, &GlobalShortcuts::hidePopupsTriggered);
+
+    KGlobalAccel::self()->setGlobalShortcut(m_hidePopupsAction, QKeySequence());
 }

 GlobalShortcuts::~GlobalShortcuts() = default;
diff --git a/applets/notifications/globalshortcuts.h b/applets/notifications/globalshortcuts.h
index 60d097344d..44918de321 100644
--- a/applets/notifications/globalshortcuts.h
+++ b/applets/notifications/globalshortcuts.h
@@ -26,8 +26,10 @@ public:
 Q_SIGNALS:
     void toggleDoNotDisturbTriggered();
     void clearHistoryTriggered();
+    void hidePopupsTriggered();

 private:
     QAction *m_toggleDoNotDisturbAction;
     QAction *m_clearHistoryAction;
+    QAction *m_hidePopupsAction;
 };
